//! Header and control block fields over their ranges (SPEC 8.2, Appendix B),
//! and header-first reception: Rust transmitter to Rust receiver with the
//! receiver told only the width and mask. (The mic and repeater FM channel
//! profiles are covered by the `hdr_*` fixtures in `tests/rx_fixtures.rs`,
//! generated by the simulator's `FmChannel`.)

use cairn_phy::channel::{Rng, awgn};
use cairn_phy::fields::{
    self, AckBlock, Address, CalReportBlock, CalRequestBlock, ConnectBlock, ControlBlock, FieldError, Header, IdBlock,
    PathBlock, frame_type,
};
use cairn_phy::rx::HeaderError;
use cairn_phy::{FrameConfig, LinkState, Receiver, RxOptions, Transmitter, params};

fn station(ssid: u8) -> Address {
    Address::new("N0CALL", ssid).unwrap()
}

fn round_trip_header(h: &Header) {
    let bits = h.bits().unwrap();
    assert_eq!(bits.len(), 144);
    assert_eq!(&Header::unpack(&bits).unwrap(), h);
}

fn round_trip_control(c: &ControlBlock) {
    let bits = c.bits().unwrap();
    assert_eq!(bits.len(), 256);
    assert_eq!(&ControlBlock::unpack(&bits).unwrap(), c);
}

#[test]
fn addresses() {
    for call in ["A", "N0CALL", "N0C/-", "0", "ZZZZZZ"] {
        for ssid in [0, 7, 15] {
            let a = Address::new(call, ssid).unwrap();
            assert_eq!(Address::decode(a.encode()).unwrap(), a);
        }
    }
    let long = Address::new("n0call/7", 4).unwrap();
    assert!(matches!(long, Address::Hashed { ssid: 4, .. }));
    assert_eq!(long.encode() >> 34, 63);
    assert_eq!(Address::decode(long.encode()).unwrap(), long);
    assert_eq!(Address::decode(fields::BROADCAST_VALUE).unwrap(), Address::Broadcast);
    for bad in [0u64, 39 << 34, (1 << 34) | (1 << 22), (1 << 34) | (63 << 28)] {
        assert!(Address::decode(bad).is_err(), "{bad:x}");
    }
    for bad in ["", "N0 CALL", "N0CALL!", "ABCDEFGHIJK"] {
        assert!(Address::new(bad, 0).is_err(), "{bad}");
    }
    assert!(Address::new("N0CALL", 16).is_err());
}

#[test]
fn header_field_ranges_and_errors() {
    let mut rng = Rng::new(3);
    for seq in [0u16, 1, 32767, 65535] {
        for mcs in [0u8, 6, 7, 15] {
            for n_control in 0..4 {
                for n_data in [0, 1, 2, 64, 127, 128] {
                    let mut h = Header::new((rng.next_u64() % 32) as u8, station(1), Address::Broadcast);
                    h.sequence = seq;
                    h.mcs = mcs;
                    h.n_control = n_control;
                    h.n_data = n_data;
                    let f = rng.bits(4);
                    (h.more_fragments, h.session, h.probe, h.repeat) = (f[0] == 1, f[1] == 1, f[2] == 1, f[3] == 1);
                    round_trip_header(&h);
                }
            }
        }
    }
    let mut h = Header::new(frame_type::DATA, station(1), station(2));
    h.n_data = 129;
    assert!(h.bits().is_err());
    h.n_data = 1;
    h.mcs = 16;
    assert!(h.bits().is_err());
    // Every single-bit error is caught; flag bit 0 must agree with the count.
    let mut h = Header::new(frame_type::CONNECT, station(1), station(2));
    h.n_control = 2;
    h.probe = true;
    let bits = h.bits().unwrap();
    for i in 0..144 {
        let mut c = bits.clone();
        c[i] ^= 1;
        assert!(Header::unpack(&c).is_err(), "bit {i}");
    }
    let mut msg = h.message_bits().unwrap();
    msg[15] = 0;
    assert_eq!(Header::unpack(&cairn_phy::crc::append_crc(&msg)), Err(FieldError::ControlFlag));
    msg[15] = 1;
    msg[0..3].copy_from_slice(&[0, 1, 0]);
    assert_eq!(Header::unpack(&cairn_phy::crc::append_crc(&msg)), Err(FieldError::Version(2)));
}

#[test]
fn control_field_ranges() {
    let mut rng = Rng::new(5);
    for _ in 0..40 {
        let bits = rng.bits(128);
        let mask = (rng.next_u64() & 1 == 1).then(|| rng.next_u64() & fields::ALL_TONES);
        round_trip_control(&ControlBlock::Ack(AckBlock {
            base_sequence: rng.next_u64() as u16,
            bitmap: AckBlock::bitmap_from(&bits.iter().map(|&b| b == 1).collect::<Vec<_>>()),
            requested_mcs: (rng.next_u64() % 16) as u8,
            snr_q: rng.next_u64() as u8,
            block_errors: rng.next_u64() as u8,
            tone_mask: mask,
            reprobe: rng.next_u64() & 1 == 1,
            long_prefix: rng.next_u64() & 1 == 1,
            distortion: (rng.next_u64() % 8) as u8,
            adc_clipped: rng.next_u64() & 1 == 1,
            mask_id: (rng.next_u64() % 4) as u8,
        }));
    }
    assert_eq!((fields::snr_code(-3.0), fields::snr_code(17.125), fields::snr_code(99.0)), (0, 69, 255));
    for cap in [23, 39, 55] {
        for mft in [5, 20, 40] {
            round_trip_control(&ControlBlock::Connect(ConnectBlock {
                session_id: 0xFFFF,
                capabilities: 0xFFFF,
                width_cap: cap,
                requested_mcs: 15,
                max_frame_time: mft,
                tone_mask: 0x00AA_AAAA_AAAA_AAAA,
                dictionary_ids: [0, 1, u32::MAX, 0x1234_5678],
                more_dictionaries: true,
                resume: true,
            }));
        }
    }
    for bad in [
        ConnectBlock { width_cap: 22, ..Default::default() },
        ConnectBlock { max_frame_time: 41, ..Default::default() },
    ] {
        assert!(ControlBlock::Connect(bad).bits().is_err());
    }
    round_trip_control(&ControlBlock::CalRequest(CalRequestBlock::default()));
    round_trip_control(&ControlBlock::CalReport(CalReportBlock {
        amplitudes: [0, 255, 1, 2, 3, 4, 5, 6],
        distortion: [15, 0, 1, 2, 3, 4, 5, 6],
        clipped: [true, false, true, false, false, false, false, true],
        sweep_valid: true,
    }));
    for (call, grid) in [("N0CALL", None), ("N0CALL/7", Some("FN31")), ("ABCDEFGHIJ", Some("AA00AA"))] {
        round_trip_control(&ControlBlock::Id(IdBlock { callsign: call.into(), ssid: 3, grid: grid.map(Into::into) }));
    }
    round_trip_control(&ControlBlock::Path(PathBlock {
        entries: vec![Address::new("WIDE1", 1).unwrap(), Address::new("N0CALL/7", 2).unwrap()],
        hops: 3,
        used: [true, false],
        via: true,
    }));
    let mut b = ControlBlock::CalRequest(CalRequestBlock::default()).bits().unwrap();
    b[100] ^= 1;
    assert_eq!(ControlBlock::unpack(&b), Err(FieldError::Crc));
}

fn ack(n: usize) -> ControlBlock {
    ControlBlock::Ack(AckBlock {
        base_sequence: 10,
        bitmap: AckBlock::bitmap_from(&vec![true; n]),
        requested_mcs: 2,
        snr_q: fields::snr_code(15.0),
        ..Default::default()
    })
}

fn padded(x: &[f64]) -> Vec<f64> {
    let mut y = vec![0.0; 600];
    y.extend_from_slice(x);
    y.extend(vec![0.0; 600]);
    y
}

#[test]
fn header_first_through_awgn() {
    let mut rng = Rng::new(21);
    let mut h = Header::new(frame_type::DATA, station(1), station(2));
    (h.sequence, h.mcs, h.n_control, h.n_data, h.session) = (500, 2, 1, 3, true);
    let link = LinkState::default();
    for _ in 0..3 {
        let payloads: Vec<Vec<u8>> = (0..3).map(|_| rng.bits(params::DATA_PAYLOAD_BITS)).collect();
        let frame = Transmitter::new().build_frame(&h, &[ack(4)], &payloads, &link).unwrap();
        let x = padded(&frame.output());
        let data = &frame.output()[frame.config.first_data() * frame.config.stride()..];
        let p = data.iter().map(|v| v * v).sum::<f64>() / data.len() as f64;
        let y = awgn(&x, 9.0, 24, &mut rng, Some(p));
        let r = Receiver::new().detect_and_receive(&y, &link, &RxOptions::default()).unwrap();
        assert_eq!(r.header.as_ref(), Some(&h), "{:?}", r.header_error);
        let cfg = r.config.as_ref().unwrap();
        assert_eq!((cfg.n_blocks, cfg.n_control, cfg.mcs), (3, 1, 2));
        assert_eq!(r.controls, vec![Some(ack(4))]);
        assert!(r.block_ok.iter().all(|&v| v));
        assert_eq!(r.block_bits, frame.block_bits);
    }
}

#[test]
fn header_only_frame() {
    let mut h = Header::new(frame_type::PROBE, station(1), station(2));
    h.mcs = 6; // ignored without data blocks: the frame is clipped at 7 dB
    let frame = Transmitter::new().build_frame(&h, &[], &[], &LinkState::default()).unwrap();
    assert_eq!(frame.config.total_symbols(), 11);
    assert_eq!(frame.config.clip_db, params::CLIP_DB_REFERENCE);
    let r = Receiver::new().detect_and_receive(&padded(&frame.output()), &LinkState::default(), &RxOptions::default());
    let r = r.unwrap();
    assert_eq!(r.header, Some(h));
    assert!(r.block_ok.is_empty() && r.control_ok.is_empty());
}

#[test]
fn controls_with_probe_masked_long_prefix() {
    let mut rng = Rng::new(8);
    let usable: Vec<usize> = (0..56).filter(|k| ![1, 9, 25].contains(k)).collect();
    let tx_link =
        LinkState { width: 30, usable: Some(usable.clone()), cp: Some(params::CP_LONG), ..Default::default() };
    let rx_link = LinkState { width: 30, usable: Some(usable.clone()), ..Default::default() };
    // CONNECT-ACK: probe, two control blocks, no data.
    let mut h = Header::new(frame_type::CONNECT_ACK, station(2), station(1));
    (h.n_control, h.session, h.probe) = (2, true, true);
    let cb = ControlBlock::Connect(ConnectBlock {
        session_id: 7,
        width_cap: 29,
        requested_mcs: 3,
        tone_mask: fields::tones_to_mask(&usable),
        ..Default::default()
    });
    let frame = Transmitter::new().build_frame(&h, &[cb.clone(), ack(8)], &[], &tx_link).unwrap();
    assert!(frame.config.has_probe && frame.config.cp == params::CP_LONG);
    assert_eq!(frame.config.control_tones.len(), 22); // CONNECT-ACK is unmasked (ADR 0011 mask-id)
    let y = awgn(&padded(&frame.output()), 14.0, 24, &mut rng, None);
    let r = Receiver::new().detect_and_receive(&y, &rx_link, &RxOptions::default()).unwrap();
    assert_eq!(r.header.as_ref(), Some(&h));
    assert_eq!(r.config.as_ref().unwrap().cp, params::CP_LONG);
    assert_eq!(r.controls, vec![Some(cb), Some(ack(8))]);
    // DATA after an ACK block at width 30, masked.
    let mut h2 = Header::new(frame_type::DATA, station(1), station(2));
    (h2.sequence, h2.mcs, h2.n_control, h2.n_data, h2.session, h2.probe) = (3, 3, 1, 4, true, true);
    let payloads: Vec<Vec<u8>> = (0..4).map(|_| rng.bits(params::DATA_PAYLOAD_BITS)).collect();
    let frame = Transmitter::new().build_frame(&h2, &[ack(3)], &payloads, &tx_link).unwrap();
    let y = awgn(&padded(&frame.output()), 22.0, 30, &mut rng, None);
    let r = Receiver::new().detect_and_receive(&y, &rx_link, &RxOptions::default()).unwrap();
    assert_eq!(r.header.as_ref(), Some(&h2));
    assert!(r.control_ok.iter().chain(&r.block_ok).all(|&v| v));
    assert_eq!(r.block_bits, frame.block_bits);
}

#[test]
fn header_and_control_failures() {
    let mut rng = Rng::new(4);
    let link = LinkState::default();
    let mut h = Header::new(frame_type::DATA, station(1), station(2));
    (h.mcs, h.n_control, h.n_data, h.session) = (1, 2, 2, true);
    let id = ControlBlock::Id(IdBlock { callsign: "N0CALL".into(), ssid: 1, grid: None });
    let payloads: Vec<Vec<u8>> = (0..2).map(|_| rng.bits(params::DATA_PAYLOAD_BITS)).collect();
    let frame = Transmitter::new().build_frame(&h, &[ack(4), id.clone()], &payloads, &link).unwrap();
    let cfg = frame.config.clone();
    let stride = cfg.stride();
    let x = padded(&frame.samples);
    let opts = RxOptions::default();

    // Header symbols destroyed: no header, nothing else decoded.
    let mut y = x.clone();
    for (i, v) in y[600 + 4 * stride..600 + 11 * stride].iter_mut().enumerate() {
        *v = 3.0 * rng.normal() + if i % 2 == 0 { 0.5 } else { -0.5 };
    }
    let r = Receiver::new().receive_header_first(&y, &link, 600, params::CP_SHORT, &opts);
    assert!(r.header.is_none() && r.config.is_none() && r.block_ok.is_empty());
    assert_eq!(r.header_error, Some(HeaderError::NotDecoded));

    // CRC passes, fields malformed (version 2): refused.
    let mut msg = h.message_bits().unwrap();
    msg[0..3].copy_from_slice(&[0, 1, 0]);
    let cmsgs = vec![ack(4).message_bits().unwrap(), id.message_bits().unwrap()];
    let bad = Transmitter::new().build_with_controls(&cfg, &msg, &cmsgs, &payloads);
    let r = Receiver::new().receive_header_first(&padded(&bad.samples), &link, 600, params::CP_SHORT, &opts);
    assert!(r.header_ok && r.header.is_none() && r.block_ok.is_empty());
    assert_eq!(r.header_error, Some(HeaderError::Fields(FieldError::Version(2))));

    // A reserved rung with data blocks describes no frame.
    let mut odd = Header::new(frame_type::DATA, station(1), station(2));
    (odd.mcs, odd.n_data) = (9, 1);
    let one = FrameConfig::new(24, 0, 1).unwrap();
    let f = Transmitter::new().build(&one, &odd.message_bits().unwrap(), &payloads[..1]);
    let r = Receiver::new().receive_header_first(&padded(&f.samples), &link, 600, params::CP_SHORT, &opts);
    assert!(matches!(r.header_error, Some(HeaderError::Config(_))) && r.header.is_none());

    // Second control block destroyed: it fails alone, the rest decodes.
    let ct = cfg.control_tones.len();
    let s2 = cfg.first_control() + (256 + 10) / ct;
    let mut y = x.clone();
    for v in &mut y[600 + s2 * stride..600 + (s2 + 6) * stride] {
        *v = -*v;
    }
    let r = Receiver::new().receive_header_first(&y, &link, 600, params::CP_SHORT, &opts);
    assert_eq!(r.header.as_ref(), Some(&h));
    assert_eq!(r.control_ok, vec![true, false]);
    assert_eq!(r.controls, vec![Some(ack(4)), None]);
    assert!(r.block_ok.iter().all(|&v| v));
}

#[test]
fn build_frame_checks_counts() {
    let mut h = Header::new(frame_type::DATA, station(1), station(2));
    (h.mcs, h.n_control, h.n_data) = (2, 1, 2);
    let mut tx = Transmitter::new();
    assert!(tx.build_frame(&h, &[], &[vec![0; 1008], vec![0; 1008]], &LinkState::default()).is_err());
    assert!(tx.build_frame(&h, &[ack(1)], &[vec![0; 1008]], &LinkState::default()).is_err());
    // Wider than 24 tones without the probe flag: no channel estimate above
    // tone 23, so the frame is refused, and build_frame sets the flag itself
    // (ADR 0007 width-probe-every-wide-frame).
    let wide = LinkState { width: 30, ..Default::default() };
    assert_eq!(FrameConfig::from_header(&h, &wide, 60), Err(cairn_phy::ConfigError::NeedsProbe));
    assert_eq!(FrameConfig::new(30, 2, 2).unwrap().with_probe(false), Err(cairn_phy::ConfigError::NeedsProbe));
    let f = tx.build_frame(&h, &[ack(1)], &[vec![0; 1008], vec![0; 1008]], &wide).unwrap();
    assert!(f.config.has_probe && f.header.as_ref().unwrap().probe);
    let cfg = FrameConfig::new(30, 3, 2).unwrap().with_controls(3).unwrap();
    assert_eq!(cfg.control_symbols(), (3 * 512usize).div_ceil(44));
    assert_eq!(FrameConfig::new(24, 0, 0).unwrap().with_controls(1).unwrap().control_symbols(), 12);
}
